-- Canonical schema, ownership-safe keys, RLS, and private attachment storage.
-- Design: docs/architecture/schema.md
-- Rollback is a later migration. Do not edit this file after it is applied.

create or replace function public.touch_row()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.updated_at = now();
  if tg_op = 'UPDATE' then
    new.version = old.version + 1;
  end if;
  return new;
end;
$$;

create or replace function public.prevent_owner_change()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.owner_id is distinct from old.owner_id then
    raise exception 'owner_id cannot change';
  end if;
  return new;
end;
$$;

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text not null default 'Reader' check (char_length(display_name) between 1 and 80),
  timezone text not null default 'UTC' check (char_length(timezone) between 1 and 80),
  week_starts_on smallint not null default 1 check (week_starts_on in (0, 1)),
  density text not null default 'comfortable' check (density in ('comfortable', 'compact')),
  ai_permitted boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  deleted_at timestamptz
);

create table public.user_devices (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  label text not null check (char_length(label) between 1 and 80),
  last_seen_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  unique (owner_id, id)
);

create table public.work_items (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  title text not null check (char_length(title) between 1 and 200),
  body text not null default '',
  category text not null check (category in ('personal', 'home', 'work', 'admin', 'learning')),
  severity text not null check (severity in ('critical', 'high', 'medium', 'low')),
  status text not null default 'open' check (status in ('open', 'done', 'cancelled')),
  due_on date,
  due_at timestamptz,
  estimate_minutes integer check (estimate_minutes is null or estimate_minutes between 0 and 20160),
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  deleted_at timestamptz,
  unique (owner_id, id),
  constraint work_items_one_deadline check (due_on is null or due_at is null),
  constraint work_items_done_time check ((status = 'done') = (completed_at is not null))
);

create table public.recurrence_series (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  frequency text not null check (frequency in ('daily', 'weekly', 'monthly', 'yearly')),
  interval_count integer not null default 1 check (interval_count >= 1),
  timezone text not null check (char_length(timezone) between 1 and 80),
  starts_on date not null,
  until_on date,
  occurrence_count integer check (occurrence_count is null or occurrence_count >= 1),
  local_start_time time,
  duration_minutes integer check (duration_minutes is null or duration_minutes between 1 and 1440),
  all_day boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  deleted_at timestamptz,
  unique (owner_id, id),
  constraint recurrence_one_end check (until_on is null or occurrence_count is null),
  constraint recurrence_until_order check (until_on is null or until_on >= starts_on),
  constraint recurrence_wall_time check (all_day = (local_start_time is null))
);

create table public.events (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  series_id uuid,
  occurrence_on date,
  title text not null check (char_length(title) between 1 and 200),
  body text not null default '',
  category text not null check (category in ('personal', 'home', 'work', 'admin', 'learning')),
  all_day boolean not null default false,
  starts_on date,
  ends_on date,
  starts_at timestamptz,
  ends_at timestamptz,
  timezone text not null check (char_length(timezone) between 1 and 80),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  deleted_at timestamptz,
  unique (owner_id, id),
  foreign key (owner_id, series_id) references public.recurrence_series (owner_id, id) on delete cascade,
  constraint events_all_day_dates check (
    (all_day and starts_on is not null and ends_on is not null and ends_on >= starts_on and starts_at is null and ends_at is null)
    or
    (not all_day and starts_at is not null and ends_at is not null and ends_at > starts_at and starts_on is null and ends_on is null)
  ),
  constraint events_occurrence_pair check ((series_id is null) = (occurrence_on is null))
);

create table public.recurrence_exceptions (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  series_id uuid not null,
  occurrence_on date not null,
  kind text not null check (kind in ('skip', 'cancel', 'override')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  unique (owner_id, id),
  unique (owner_id, series_id, occurrence_on),
  foreign key (owner_id, series_id) references public.recurrence_series (owner_id, id) on delete cascade
);

create table public.notes (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  work_item_id uuid,
  event_id uuid,
  title text not null check (char_length(title) between 1 and 200),
  body text not null check (char_length(body) >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  deleted_at timestamptz,
  unique (owner_id, id),
  foreign key (owner_id, work_item_id) references public.work_items (owner_id, id) on delete cascade,
  foreign key (owner_id, event_id) references public.events (owner_id, id) on delete cascade,
  constraint notes_one_parent check (num_nonnulls(work_item_id, event_id) <= 1)
);

create table public.reminders (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  work_item_id uuid,
  event_id uuid,
  title text not null check (char_length(title) between 1 and 200),
  remind_at timestamptz,
  remind_on date,
  offset_minutes integer check (offset_minutes is null or offset_minutes between -10080 and 10080),
  channel text not null check (channel in ('in_app', 'email', 'push')),
  status text not null default 'active' check (status in ('active', 'cancelled')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  deleted_at timestamptz,
  unique (owner_id, id),
  foreign key (owner_id, work_item_id) references public.work_items (owner_id, id) on delete cascade,
  foreign key (owner_id, event_id) references public.events (owner_id, id) on delete cascade,
  constraint reminders_one_schedule check (
    num_nonnulls(remind_at, remind_on, offset_minutes) = 1
  ),
  constraint reminders_offset_needs_event check (offset_minutes is null or event_id is not null)
);

create table public.planning_blocks (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  work_item_id uuid not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  status text not null check (status in ('active', 'completed', 'cancelled', 'obsolete')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  deleted_at timestamptz,
  unique (owner_id, id),
  foreign key (owner_id, work_item_id) references public.work_items (owner_id, id) on delete cascade,
  constraint planning_blocks_order check (ends_at > starts_at)
);

create table public.task_effort_logs (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  work_item_id uuid not null,
  started_at timestamptz not null,
  ended_at timestamptz not null,
  minutes integer not null check (minutes between 1 and 1440),
  note text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  unique (owner_id, id),
  foreign key (owner_id, work_item_id) references public.work_items (owner_id, id) on delete cascade,
  constraint effort_order check (ended_at > started_at)
);

create table public.auto_surface_states (
  owner_id uuid not null references public.profiles (id) on delete cascade,
  work_item_id uuid not null,
  dismissed_at timestamptz,
  restored_at timestamptz,
  eligibility_signature text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  primary key (owner_id, work_item_id),
  foreign key (owner_id, work_item_id) references public.work_items (owner_id, id) on delete cascade
);

create table public.operation_batches (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  label text not null default '' check (char_length(label) <= 120),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  unique (owner_id, id)
);

create table public.operation_journal (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  batch_id uuid,
  entity_type text not null check (char_length(entity_type) between 1 and 80),
  entity_id uuid not null,
  before_snapshot jsonb,
  after_snapshot jsonb,
  version_after integer check (version_after is null or version_after > 0),
  undone_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  unique (owner_id, id),
  foreign key (owner_id, batch_id) references public.operation_batches (owner_id, id) on delete cascade
);

create table public.operation_batch_items (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  batch_id uuid not null,
  journal_id uuid not null,
  created_at timestamptz not null default now(),
  unique (owner_id, id),
  unique (owner_id, batch_id, journal_id),
  foreign key (owner_id, batch_id) references public.operation_batches (owner_id, id) on delete cascade,
  foreign key (owner_id, journal_id) references public.operation_journal (owner_id, id) on delete cascade
);

create table public.notification_outbox (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  reminder_id uuid,
  channel text not null check (channel in ('in_app', 'email', 'push')),
  payload jsonb not null default '{}'::jsonb,
  status text not null default 'pending' check (status in ('pending', 'claimed', 'delivered', 'failed', 'dead')),
  available_at timestamptz not null default now(),
  claimed_at timestamptz,
  claim_token uuid,
  attempt_count integer not null default 0 check (attempt_count >= 0),
  idempotency_key text not null check (char_length(idempotency_key) between 8 and 200),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  unique (owner_id, id),
  unique (owner_id, idempotency_key),
  foreign key (owner_id, reminder_id) references public.reminders (owner_id, id) on delete cascade
);

create table public.notification_deliveries (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  outbox_id uuid not null,
  attempt integer not null check (attempt >= 1),
  status text not null check (status in ('succeeded', 'failed')),
  provider_message_id text,
  error text,
  created_at timestamptz not null default now(),
  unique (owner_id, id),
  unique (owner_id, outbox_id, attempt),
  foreign key (owner_id, outbox_id) references public.notification_outbox (owner_id, id) on delete cascade
);

create table public.idempotency_keys (
  owner_id uuid not null references public.profiles (id) on delete cascade,
  key text not null check (char_length(key) between 8 and 200),
  request_hash text not null check (char_length(request_hash) between 1 and 128),
  response_status integer check (response_status is null or response_status between 100 and 599),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  primary key (owner_id, key)
);

create table public.ai_approval_records (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  proposal_id uuid not null,
  payload_hash text not null check (payload_hash ~ '^[0-9a-f]{64}$'),
  resource_versions jsonb not null default '{}'::jsonb,
  expires_at timestamptz not null,
  status text not null default 'pending' check (status in ('pending', 'consumed', 'rejected', 'expired')),
  consumed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  unique (owner_id, id),
  unique (owner_id, proposal_id),
  constraint ai_approval_consumed_pair check ((status = 'consumed') = (consumed_at is not null))
);

create table public.attachments (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  storage_path text not null unique,
  mime_type text not null check (mime_type in ('image/jpeg', 'image/png', 'image/webp', 'application/pdf', 'text/plain')),
  byte_size integer not null check (byte_size between 1 and 10485760),
  work_item_id uuid,
  event_id uuid,
  note_id uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1 check (version > 0),
  deleted_at timestamptz,
  unique (owner_id, id),
  foreign key (owner_id, work_item_id) references public.work_items (owner_id, id) on delete cascade,
  foreign key (owner_id, event_id) references public.events (owner_id, id) on delete cascade,
  foreign key (owner_id, note_id) references public.notes (owner_id, id) on delete cascade,
  constraint attachments_one_parent check (num_nonnulls(work_item_id, event_id, note_id) <= 1),
  constraint attachments_owner_path check (storage_path = owner_id::text || '/' || id::text)
);

create index work_items_owner_due_idx on public.work_items (owner_id, due_on) where deleted_at is null;
create index work_items_owner_status_idx on public.work_items (owner_id, status) where deleted_at is null;
create index events_owner_start_idx on public.events (owner_id, starts_at) where deleted_at is null;
create index events_owner_day_idx on public.events (owner_id, starts_on) where deleted_at is null;
create index reminders_owner_instant_idx on public.reminders (owner_id, remind_at) where deleted_at is null;
create index planning_blocks_owner_start_idx on public.planning_blocks (owner_id, starts_at) where deleted_at is null;
create index outbox_pending_idx on public.notification_outbox (available_at) where status = 'pending';
create index idempotency_expiry_idx on public.idempotency_keys (expires_at);
create index ai_approvals_owner_status_idx on public.ai_approval_records (owner_id, status);

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id)
  values (new.id)
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

create or replace function public.delete_owned_storage()
returns trigger
language plpgsql
security definer
set search_path = public, storage
as $$
begin
  delete from storage.objects
  where bucket_id = 'attachments'
    and (storage.foldername(name))[1] = old.id::text;
  return old;
end;
$$;

create trigger profiles_delete_storage
  before delete on public.profiles
  for each row execute function public.delete_owned_storage();

do $$
declare
  mutable text;
begin
  foreach mutable in array array[
    'profiles',
    'user_devices',
    'work_items',
    'recurrence_series',
    'events',
    'recurrence_exceptions',
    'notes',
    'reminders',
    'planning_blocks',
    'task_effort_logs',
    'auto_surface_states',
    'operation_batches',
    'operation_journal',
    'notification_outbox',
    'ai_approval_records',
    'attachments'
  ]
  loop
    execute format(
      'create trigger %I_touch before update on public.%I for each row execute function public.touch_row()',
      mutable,
      mutable
    );
  end loop;
end $$;

do $$
declare
  owned text;
begin
  foreach owned in array array[
    'user_devices',
    'work_items',
    'recurrence_series',
    'events',
    'recurrence_exceptions',
    'notes',
    'reminders',
    'planning_blocks',
    'task_effort_logs',
    'auto_surface_states',
    'operation_batches',
    'operation_journal',
    'operation_batch_items',
    'notification_outbox',
    'notification_deliveries',
    'idempotency_keys',
    'ai_approval_records',
    'attachments'
  ]
  loop
    execute format(
      'create trigger %I_owner before update on public.%I for each row execute function public.prevent_owner_change()',
      owned,
      owned
    );
  end loop;
end $$;

revoke all on function public.touch_row() from public, anon, authenticated;
revoke all on function public.prevent_owner_change() from public, anon, authenticated;
revoke all on function public.handle_new_user() from public, anon, authenticated;
revoke all on function public.delete_owned_storage() from public, anon, authenticated;

do $$
declare
  t text;
begin
  foreach t in array array[
    'profiles',
    'user_devices',
    'work_items',
    'recurrence_series',
    'events',
    'recurrence_exceptions',
    'notes',
    'reminders',
    'planning_blocks',
    'task_effort_logs',
    'auto_surface_states',
    'operation_batches',
    'operation_journal',
    'operation_batch_items',
    'notification_outbox',
    'notification_deliveries',
    'idempotency_keys',
    'ai_approval_records',
    'attachments'
  ]
  loop
    execute format('revoke all on table public.%I from public, anon', t);
    execute format('grant select, insert, update, delete on table public.%I to authenticated', t);
    execute format('grant all on table public.%I to service_role', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
  end loop;
end $$;

create policy profiles_select on public.profiles
  for select to authenticated
  using (id = (select auth.uid()));
create policy profiles_insert on public.profiles
  for insert to authenticated
  with check (id = (select auth.uid()));
create policy profiles_update on public.profiles
  for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));
create policy profiles_delete on public.profiles
  for delete to authenticated
  using (id = (select auth.uid()));

do $$
declare
  t text;
begin
  foreach t in array array[
    'user_devices',
    'work_items',
    'recurrence_series',
    'events',
    'recurrence_exceptions',
    'notes',
    'reminders',
    'planning_blocks',
    'task_effort_logs',
    'auto_surface_states',
    'operation_batches',
    'operation_journal',
    'operation_batch_items',
    'notification_outbox',
    'notification_deliveries',
    'idempotency_keys',
    'ai_approval_records',
    'attachments'
  ]
  loop
    execute format(
      'create policy %I on public.%I for select to authenticated using (owner_id = (select auth.uid()))',
      t || '_select',
      t
    );
    execute format(
      'create policy %I on public.%I for insert to authenticated with check (owner_id = (select auth.uid()))',
      t || '_insert',
      t
    );
    execute format(
      'create policy %I on public.%I for update to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()))',
      t || '_update',
      t
    );
    execute format(
      'create policy %I on public.%I for delete to authenticated using (owner_id = (select auth.uid()))',
      t || '_delete',
      t
    );
  end loop;
end $$;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'attachments',
  'attachments',
  false,
  10485760,
  array['image/jpeg', 'image/png', 'image/webp', 'application/pdf', 'text/plain']::text[]
);

create policy attachments_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'attachments'
    and (storage.foldername(name))[1] = (select auth.uid()::text)
  );

create policy attachments_insert on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'attachments'
    and (storage.foldername(name))[1] = (select auth.uid()::text)
    and name !~ '\.\.'
    and lower(storage.extension(name)) in ('jpg', 'jpeg', 'png', 'webp', 'pdf', 'txt')
    and coalesce(metadata->>'mimetype', '') in ('image/jpeg', 'image/png', 'image/webp', 'application/pdf', 'text/plain')
    and coalesce((metadata->>'size')::bigint, 0) between 1 and 10485760
  );

create policy attachments_update on storage.objects
  for update to authenticated
  using (
    bucket_id = 'attachments'
    and (storage.foldername(name))[1] = (select auth.uid()::text)
  )
  with check (
    bucket_id = 'attachments'
    and (storage.foldername(name))[1] = (select auth.uid()::text)
  );

create policy attachments_delete on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'attachments'
    and (storage.foldername(name))[1] = (select auth.uid()::text)
  );
